FeatureScript 3044;
import(path : "onshape/std/geometry.fs", version : "3044.0");

export function filletInput(context is Context, id is Id, definition is map)
{
    var s0 = newSketchOnPlane(context, id + "s0", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(s0, "e0", { "firstCorner" : vector(0, 0) * millimeter, "secondCorner" : vector(20, 10) * millimeter });
    skSolve(s0);
    opExtrude(context, id + "x1", { "entities" : qSketchRegion(id + "s0"), "direction" : vector(0, 0, 1), "endBound" : BoundingType.BLIND, "endDepth" : 8 * millimeter });
}

